INSERT INTO public.config_schema VALUES ('regime.prob_min', 'float', '0.30', 0, 1, NULL, false, 1, 'Minimum regime probability to pass gate (safety floor)', '2026-05-29 21:42:32.145222+00');
INSERT INTO public.config_schema VALUES ('regime.dur_min', 'int', '1', 1, 100, NULL, false, 1, 'Minimum regime duration in bars to pass gate', '2026-05-29 21:42:32.146117+00');
INSERT INTO public.config_schema VALUES ('threshold.dividend.max_failure_fraction', 'float', '0.05', 0, 1, NULL, false, 1, '[conventional] Largest share of a dividend_event_writer run''s symbols that may fail derivation or write before the unit exits nonzero instead of completing with a partial status; gates unit failure vs partial (per-name isolation, D-191-O). Not an ML learning target.', '2026-10-26 11:43:38.660505+00');
INSERT INTO public.config_schema VALUES ('infra.alpaca.data_feed', 'string', 'iex', NULL, NULL, NULL, false, 1, '[rca_analysis] The market data feed the alpaca capture leaves ask (scripts/ops/bars/ops_bar_nightly.py via AlpacaProvider). Free-plan Alpaca rejects recent SIP data (measured live 2026-10-26: a bars window reaching within ~15 minutes of now on feed=sip answers 403 "subscription does not permit querying recent SIP data"), so the nightly''s recent tail is asked on iex. IEX volume is a thin, differently-based answer (SPY 5m tail n=1 vs sip n=2428); rows written from it carry bar_kind iex_rth, never sip_rth. Not an ML learning target.', '2026-10-26 13:44:44.940442+00');
INSERT INTO public.config_schema VALUES ('infra.alpaca.sip_recent_lag_minutes', 'int', '20', 16, 1440, NULL, false, 1, '[rca_analysis] Minutes the alpaca nightly holds its SIP window end back from now. Free-plan Alpaca 403s a feed=sip window ending within about 15 minutes of now (measured 2026-10-26: end=now 403, end=now-20min 200). Not an ML learning target.', '2026-10-26 14:22:30.240915+00');
INSERT INTO public.config_schema VALUES ('roll.monitor_window_size', 'int', '100', 10, 10000, NULL, false, 1, 'Rolling window size for roll monitoring', '2026-05-29 21:42:32.148649+00');
INSERT INTO public.config_schema VALUES ('roll.threshold_default', 'float', '1.2', 0.1, 10, NULL, false, 1, 'Default volume ratio threshold for roll detection', '2026-05-29 21:42:32.149092+00');
INSERT INTO public.config_schema VALUES ('roll.postroll_bars', 'int', '10', 0, 1000, NULL, false, 1, 'Bars to monitor after a roll event', '2026-05-29 21:42:32.149596+00');
INSERT INTO public.config_schema VALUES ('roll.cooldown_min', 'int', '30', 0, 1440, NULL, false, 1, 'Cooldown in minutes between roll events', '2026-05-29 21:42:32.150084+00');
INSERT INTO public.config_schema VALUES ('roll.confirmation_bars', 'int', '3', 1, 100, NULL, false, 1, 'Bars required to confirm a roll', '2026-05-29 21:42:32.150626+00');
INSERT INTO public.config_schema VALUES ('roll.time_of_day_gated', 'bool', 'true', NULL, NULL, '{true,false}', false, 1, 'Gate roll detection to market open/close windows', '2026-05-29 21:42:32.15113+00');
INSERT INTO public.config_schema VALUES ('cross_asset.window_bars', 'int', '20', 1, 1000, NULL, false, 1, 'Rolling window bars for cross-asset correlation', '2026-05-29 21:42:32.151718+00');
INSERT INTO public.config_schema VALUES ('macro.window_bars', 'int', '10', 1, 1000, NULL, false, 1, 'Rolling window bars for macro factor computation', '2026-05-29 21:42:32.1522+00');
INSERT INTO public.config_schema VALUES ('alert.lag.provider-merger', 'int', '500', NULL, NULL, NULL, false, 1, 'Consumer lag threshold for indicagent-provider-merger', '2026-05-29 22:22:51.030275+00');
INSERT INTO public.config_schema VALUES ('alert.lag.bar-aggregator', 'int', '500', NULL, NULL, NULL, false, 1, 'Consumer lag threshold for indicagent-bar-aggregator', '2026-05-29 22:22:51.030275+00');
INSERT INTO public.config_schema VALUES ('alert.lag.bar-auditor', 'int', '200', NULL, NULL, NULL, false, 1, 'Consumer lag threshold for indicagent-bar-auditor', '2026-05-29 22:22:51.030275+00');
INSERT INTO public.config_schema VALUES ('alert.lag.bar-writer', 'int', '1000', NULL, NULL, NULL, false, 1, 'Consumer lag threshold for indicagent-bar-writer', '2026-05-29 22:22:51.030275+00');
INSERT INTO public.config_schema VALUES ('ui.dashboard.refresh_seconds', 'int', '60', 5, NULL, NULL, false, 1, '[initial_estimate] Seconds between dashboard polls of the read routes. Data arrives by nightly batch, so a minute is ample. Not an ML learning target.', '2026-10-26 19:07:15.554707+00');
INSERT INTO public.config_schema VALUES ('alert.lag.cross-asset', 'int', '200', NULL, NULL, NULL, false, 1, 'Consumer lag threshold for indicagent-cross-asset', '2026-05-29 22:22:51.030275+00');
INSERT INTO public.config_schema VALUES ('alert.lag.macro-compute', 'int', '500', NULL, NULL, NULL, false, 1, 'Consumer lag threshold for indicagent-macro-compute', '2026-05-29 22:22:51.030275+00');
INSERT INTO public.config_schema VALUES ('ui.dashboard.stale_hours', 'int', '36', 1, NULL, NULL, false, 1, '[initial_estimate] A pipeline stage whose newest row is older than this many hours shows stale on the dashboard: one missed nightly batch plus slack. Not an ML learning target.', '2026-10-26 19:07:15.554707+00');
INSERT INTO public.config_schema VALUES ('ui.dashboard.dlq_window_days', 'int', '7', 1, NULL, NULL, false, 1, '[initial_estimate] Days of dlq_events the System page counts by topic and error type. Not an ML learning target.', '2026-10-26 19:07:15.554707+00');
INSERT INTO public.config_schema VALUES ('ui.dashboard.passport_refresh_seconds', 'int', '900', 5, NULL, NULL, false, 1, '[initial_estimate] Seconds an instrument passport (full bar history per timeframe and vendor) is cached by the API. History changes about once a day and each read scans every bar of the name, so a quarter hour keeps an open page from rescanning every poll. Not an ML learning target.', '2026-10-27 00:42:46.070913+00');
INSERT INTO public.config_schema VALUES ('alpha.selection.stepm.fwer', 'float', '0.05', 0.001, 0.2, NULL, false, 1, '[user_preference] Family-wise error of the Romano-Wolf StepM selection set over every counted attempt of the vintage (E18, design 7.3.2). A change needs a methodology-change-ledger entry. Not an ML learning target.', '2026-10-27 09:42:02.205316+00');
INSERT INTO public.config_schema VALUES ('alpha.selection.stepm.block_mean_sessions', 'float', '20', 2, 252, NULL, false, 1, '[conventional] Mean block length in sessions of the joint stationary bootstrap (about n^(1/3) for 4,000 sessions, rounded up). Must exceed the longest holding horizon in the universe; select_books refuses otherwise. Not an ML learning target.', '2026-10-27 09:42:02.205316+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.arbitration_gap_max_daily_moves', 'float', '4', 1, 50, NULL, false, 1, '[initial_estimate] A pre-IBKR Alpaca span longer than the basis window, not corroborated by Tradier, is admitted only when the close-to-close gap at IBKR''s first 1d bar is at most this many median absolute daily log moves of the name (SW 7.9 and GRNT 6.8 held; SVRA 2.1 and ordinary handovers 1 to 4 admitted, 2026-10-28). Read by ops_d191q_arbitration.py. Not an ML learning target.', '2026-10-28 06:50:28.142629+00');
INSERT INTO public.config_schema VALUES ('alert.lag.dlq-drain', 'int', '500', NULL, NULL, NULL, false, 1, 'Consumer lag threshold for indicagent-dlq-drain', '2026-05-29 22:22:51.030275+00');
INSERT INTO public.config_schema VALUES ('ui.dashboard.ingest_failing_fraction', 'float', '0.1', 0, 1, NULL, false, 1, '[initial_estimate] The ingest stage shows failing when more than this fraction of ohlcv_coverage rows report consecutive fetch failures; below it the failing count still shows beside the chip. A known backlog of a few hundred names (2026-10-26: 249 of 5,532) must not turn the home page permanently red. Not an ML learning target.', '2026-10-26 19:20:22.626593+00');
INSERT INTO public.config_schema VALUES ('feature.high_low_spread.window', 'int', '21', 1, 500, NULL, false, 1, '[conventional] Corwin-Schultz high_low_spread: two-bar spread estimates (negatives set to 0) averaged over this many pairs. Counted in bars at every timeframe (one key for 5m, 15m, 1h and 1d). 21 = the paper''s monthly average of daily estimates, a rationale that holds only on 1d; intraday levels are not comparable to 1d levels, and flat bars (high == low, about 1.7% of 15m bars since 2024) floor their pairs toward 0. Declared memory = window. Not an ML learning target.', '2026-10-28 01:48:59.660821+00');
INSERT INTO public.config_schema VALUES ('feature.roll_spread.window', 'int', '252', 2, 1000, NULL, false, 1, '[conventional] Roll implied spread roll_spread: serial covariance of log close changes over this many return pairs, NaN when the covariance is >= 0 (about 40% of 1d rows after warmup; the missingness is informative, never missing at random). Counted in bars at every timeframe (one key for 5m, 15m, 1h and 1d). 252 = one trading year, Roll (1984) estimated per year, a rationale that holds only on 1d; intraday levels are not comparable to 1d levels and an intraday window spans overnight returns. Declared memory = window + 1. Not an ML learning target.', '2026-10-28 01:48:59.660821+00');
INSERT INTO public.config_schema VALUES ('ui.dashboard.research_rows', 'int', '500', 1, NULL, NULL, false, 1, '[initial_estimate] Newest research_run attempts the Research page lists; the ledger grows without bound under exploration mode (E18). Counts and looks per vintage cover the whole ledger. Not an ML learning target.', '2026-10-27 09:51:58.562007+00');
INSERT INTO public.config_schema VALUES ('infra.alpaca.nightly_max_requests', 'int', '4000', 1, 100000, NULL, false, 1, '[initial_estimate] Per-run request ceiling for the alpaca nightly capture leaf (scripts/ops/bars/ops_bar_nightly.py). Sized to the full active universe: 1,529 names x 2 timeframes plus paging headroom. Not an ML learning target.', '2026-10-26 13:25:42.426932+00');
INSERT INTO public.config_schema VALUES ('infra.alpaca.nightly_deadline_minutes', 'int', '60', 5, 360, NULL, false, 1, '[initial_estimate] Wall-clock deadline in minutes for one alpaca nightly capture run. At the seeded rate limit (190 req/min) a full-universe pass needs about 16 minutes plus write time. Not an ML learning target.', '2026-10-26 13:25:42.426932+00');
INSERT INTO public.config_schema VALUES ('alpha.selection.stepm.reps', 'int', '2000', 200, 100000, NULL, false, 1, '[conventional] Bootstrap draws for StepM selection. Not an ML learning target.', '2026-10-27 09:42:02.205316+00');
INSERT INTO public.config_schema VALUES ('alpha.selection.stepm.seed', 'int', '187', 0, 2147483647, NULL, false, 1, '[initial_estimate] Seed of the StepM bootstrap index draw. Changing it changes the reported selection set and adjusted p-values; record the change. Not an ML learning target.', '2026-10-27 09:42:02.205316+00');
INSERT INTO public.config_schema VALUES ('feature.amihud.min_valid_fraction', 'float', '0.8', 0.1, 1, NULL, false, 1, '[conventional] amihud_illiq_z: minimum share of the zscore_window that must hold a valid ln(illiq) observation (a NULL-volume bar, a zero return or a non-positive close is missing); below it the row is NaN. 0.8 tolerates 50 missing bars of 252 and leaves at least 202 observations for the window moments. The window restarts at a volume-basis change. A rebuild of amihud_illiq_z and illiquidity_momentum_product follows a change. Not an ML learning target.', '2026-10-28 16:40:04.847392+00');
INSERT INTO public.config_schema VALUES ('infra.research_ledger_render.git_lock_retries', 'int', '5', 0, 30, NULL, false, 1, '[initial_estimate] research_ledger_render: retries of its single git commit when .git/index.lock is held, 2 s apart. 5 spans about 10 s; a longer hold skips the night and the next render commits the same text. Not an ML learning target.', '2026-10-28 19:22:39.203275+00');
INSERT INTO public.config_schema VALUES ('alpha.research.contribution.shapley_samples', 'int', '2000', 100, 100000, NULL, false, 1, '[initial_estimate] Contribution accounting: permutation draws for sampled Shapley above shapley_exact_max_families. Each draw refits up to K subsets (cached). Not an ML learning target.', '2026-10-29 11:47:31.429732+00');
INSERT INTO public.config_schema VALUES ('alpha.research.contribution.shapley_seed', 'int', '20261029', 0, 2147483647, NULL, false, 1, '[initial_estimate] Contribution accounting: seed of the sampled Shapley permutations. Changing it changes every sampled Shapley output and invalidates comparisons with recorded contribution blocks. Not an ML learning target.', '2026-10-29 11:47:31.429732+00');
INSERT INTO public.config_schema VALUES ('alpha.research.contribution.cluster_corr', 'float', '0.7', 0.1, 0.99, NULL, false, 1, '[initial_estimate] Contribution accounting: absolute in-fold correlation above which two members of a corpus or generated family share an accounting cluster (complete linkage, training fold only). Accounting groups never decide admission or weights. Not an ML learning target.', '2026-10-29 11:47:31.429732+00');
INSERT INTO public.config_schema VALUES ('alpha.research.contribution.shapley_exact_max_families', 'int', '8', 2, 20, NULL, false, 1, '[initial_estimate] Contribution accounting: Shapley over families is exact (every subset refit, each a counted attempt) while the book has at most this many families; above it the block records leave-one-family-out only. 8 = 254 subset refits per book; 12 would be 4,094 attempts in the StepM universe. Not an ML learning target.', '2026-10-29 11:47:31.429732+00');
INSERT INTO public.config_schema VALUES ('infra.bar_integrity.coverage_cache_lock_wait_s', 'int', '21600', 0, 28800, NULL, false, 1, '[initial_estimate] Longest the bar reconciliation audit waits for the fetcher lock before the coverage_cache verdict is skipped. 21600 s (6 h) covers one fetcher window of up to about 5 h plus the 15 min gap between windows, so the audit gets the lock at the next gap. 0 restores the single try. Not an ML learning target.', '2026-10-29 23:39:02.408874+00');
INSERT INTO public.config_schema VALUES ('threshold.ofi_continuation.magnitude_floors', 'json', '''{\"ES\":500.0,\"NQ\":200.0,\"CL\":1000.0,\"GC\":500.0,\"_default\":500.0}''', NULL, NULL, NULL, false, 1, '[initial_estimate] Per-symbol OFI magnitude floor (noise rejection gate). JSON dict keyed by base symbol. ML learning target per instrument.', '2026-06-14 23:35:45.06439+00');
INSERT INTO public.config_schema VALUES ('infra.bar_integrity.coverage_cache_lock_poll_s', 'int', '30', 1, 3600, NULL, false, 1, '[initial_estimate] Seconds between the audit''s non-blocking tries for the fetcher lock while it waits. The gap between fetcher windows is 15 min, so 30 s catches it within about 3 percent of its length; each try opens and closes its own short connection. Not an ML learning target.', '2026-10-29 23:39:02.408874+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_zone_width_atr.equity_etf', 'float', '1.5', 0, 10, NULL, false, 1, '[rca_analysis] Phase 126 zone entry width gate for equity ETF instruments. Noise-band analysis. Not a learning target until Phase 126 consumption code ships.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_zone_width_atr.forex', 'float', '1.0', 0, 10, NULL, false, 1, '[rca_analysis] Phase 126 zone entry width gate for forex instruments. Tighter spread; calibrated lower than futures/equity. Not a learning target until Phase 126 consumption code ships.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('ui.dashboard.integrity_window_hours', 'int', '12', 1, NULL, NULL, false, 1, '[initial_estimate] Hours before each integrity check''s newest row within which the Data page takes every subject''s newest result as the check''s current state. Checks run nightly and a run spans under an hour, so 12 hours holds the newest run and never the night before. Not an ML learning target.', '2026-10-27 10:33:28.986628+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_stop_distance_atr.equity', 'float', '0.5', 0.05, 5, NULL, false, 1, '[initial_estimate] Absolute floor on stop distance from entry as ATR multiple. Independent of MIN_STOP_ATR_MULTIPLIER — ML may tune that parameter but cannot breach this floor without an operator override. Equity asset class override.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_stop_distance_atr.fx', 'float', '0.3', 0.05, 5, NULL, false, 1, '[initial_estimate] Absolute floor on stop distance from entry as ATR multiple. Independent of MIN_STOP_ATR_MULTIPLIER — ML may tune that parameter but cannot breach this floor without an operator override. FX asset class override; lower due to structurally tighter forex spreads.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_stop_distance_atr.futures', 'float', '0.4', 0.05, 5, NULL, false, 1, '[initial_estimate] Absolute floor on stop distance from entry as ATR multiple. Independent of MIN_STOP_ATR_MULTIPLIER — ML may tune that parameter but cannot breach this floor without an operator override. Futures asset class override.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.hist_pacing_wait_release_s', 'float', '60.0', 1, 1500, NULL, false, 1, '[initial_estimate] Total pacing-limiter wait (seconds) above which ibkr.hist_pacing_wait_released is logged, so nightly log scans can sum throttling time. 60 s separates routine single-chunk waits (>=1 s each) from real saturation episodes and stays under the fetcher lane watchdog. Not an ML learning target.', '2026-10-31 17:03:44.030068+00');
INSERT INTO public.config_schema VALUES ('infra.grid_parity.dated_exceptions', 'json', NULL, NULL, NULL, NULL, false, 1, '[rca_analysis] The todo 573 classification (2026-10-31) of every grid_parity disagreement stamp: per symbol and timeframe, the stamps with their wave and the dimensions (price, volume) their record excuses. A wave releases its stamps as D7 dated exceptions; wave 3 stays held until the ETHA/CTVA wrong-basis archive rows are re-fetched. A missing or malformed value dates nothing: the audit can only hold more names to exact parity, never fewer. Not an ML learning target.', '2026-10-31 21:26:23.479442+00');
INSERT INTO public.config_schema VALUES ('infra.borrow.batch_size', 'int', '50', 1, 80, NULL, false, 1, '[initial_estimate] Symbols per reqMktData snapshot batch in the daily borrow capture. Subscriptions are cancelled after each batch, so the 80-subscription cap (a live-streaming cap) never binds; 50 keeps each batch well under it. Not an ML learning target.', '2026-10-31 22:34:47.346404+00');
INSERT INTO public.config_schema VALUES ('infra.borrow.batch_wait_s', 'float', '8.0', 1, 60, NULL, false, 1, '[initial_estimate] Seconds to wait after arming a batch''s subscriptions before reading the tickers; ticks 46/236 answer within a few seconds on the gateway. Rows already store NULL for a silent answer, so a too-short wait loses nothing permanently. Not an ML learning target.', '2026-10-31 22:34:47.346404+00');
INSERT INTO public.config_schema VALUES ('infra.borrow.batch_pause_s', 'float', '2.5', 0, 60, NULL, false, 1, '[initial_estimate] Pause between snapshot batches (seconds) to stay clear of market-data pacing. 1,529 names at batch 50 is about 31 batches and roughly 80 s of pause time per run. Not an ML learning target.', '2026-10-31 22:46:37.579199+00');
INSERT INTO public.config_schema VALUES ('infra.table_backup.disk_margin', 'int', '2', 1, NULL, NULL, false, 1, '[initial_estimate] Free-disk multiplier for the generic pre-drop COPY backup (scripts/ops/db/ops_table_backup.py, todo 578): a dump needs free space >= estimated output (pg_total_relation_size of the named tables) times this margin. Same role as infra.old_store_backup.disk_margin (migration 498), whose reader retires 2026-11-12 (todo 574). Not an ML learning target.', '2026-11-01 19:39:55.338488+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.history_probe_timeout_s', 'float', '60', 5, 600, NULL, false, 1, '[initial_estimate] Seconds the history-farm liveness probe (one 1d bar of infra.ibkr.history_probe_symbol) waits before the farm counts as dead and the run ends as gateway_lost (todo 538). Sits below the 90 s per-request timeout: a probe is one bar, but at fetch_concurrency 8 its answer queues behind large 5m payloads on the same socket, so a short value risks a false loss that ends a healthy run. Not an ML learning target.', '2026-11-01 23:00:22.585698+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.history_probe_symbol', 'str', 'SPY', NULL, NULL, NULL, false, 1, '[conventional] Liquid, always-trading name whose latest 1d bar the history-farm liveness probe requests (todo 538); SPY always has a daily bar and qualifies in one contract-details call. Not an ML learning target.', '2026-11-01 23:00:22.585698+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.intake_stall_exit_s', 'float', '1800', 900, 21600, NULL, false, 1, '[initial_estimate] Seconds without data intake (rows written to ohlcv_raw, or an item ending ok or no_data) after which the IBKR history fetcher ends the run as stalled instead of waiting on timeouts (todo 538 follow-up). 1800 s matches infra.ibkr.stall_abort_s and sits above one rate-limiter window (600 s) plus the longest healthy single request; one slow-farm run then costs 30 minutes instead of hours. Not an ML learning target.', '2026-11-02 03:53:14.947307+00');
INSERT INTO public.config_schema VALUES ('threshold.pilot_gate.warmup_gap_bars', 'int', '5', 0, 5000, NULL, false, 1, '[initial_estimate] Pilot gate G2 (todo 584 D3): the most bars by which a stored column''s first finite row may follow its declared feature_memory_bars before the gate fails. 5 allows an upstream NaN row or two; hma_slope_z (7,560 rows late) and the HMM outputs (5,470) are far beyond it. Not an ML learning target.', '2026-11-02 14:06:37.663813+00');
INSERT INTO public.config_schema VALUES ('threshold.pilot_gate.zero_share_max', 'float', '0.25', 0, 1, NULL, false, 1, '[initial_estimate] Pilot gate G3 (todo 584 D3): the largest exact-0.0 share of a column''s finite post-warmup rows before the gate fails it for review, for a column outside the kernels'' zero_is_state set. A 0.0 that is a fill (the 474 neutral fills) shows as a large share; a counted event rate does not. Not an ML learning target.', '2026-11-02 14:06:37.663813+00');
INSERT INTO public.config_schema VALUES ('infra.pilot_gate.names', 'json', '[]', NULL, NULL, NULL, false, 1, '[user_preference] The pilot names for the feature-column gate (todo 584 D3): ETFs prone to a degenerate regime fit, large caps, names across the volume-basis seam, recent listings, names with a bar hold, thin names, a spin-off and a name with a pre-2016 IBKR 5m segment. Read by scripts/ops/ops_feature_column_screen.py --pilot. Not an ML learning target.', '2026-11-02 14:06:37.663813+00');
INSERT INTO public.config_schema VALUES ('feature.ctf.vwap_window', 'int', '20', 2, 500, NULL, false, 1, '[initial_estimate] Rolling VWAP window, in higher-timeframe bars, behind ctf_vwap_align (todo 584 6b): sign(HTF close - VWAP of the last N HTF bars), NaN until N bars exist and on a window with no volume. Replaces a VWAP anchored at the series start, which sat on one side for years on trending names. Read via FeatureFactoryConfig.ctf_vwap_window by services/backfill_feature_factory.py and services/feature_vector_pipeline.py. Not an ML learning target.', '2026-11-03 22:36:43.663176+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.update_overlap_sessions_1d', 'int', '20', 0, 250, NULL, false, 1, '[initial_estimate] Sessions the update lane re-asks behind a name''s latest stored 1d observation, so each fresh SMART TRADES answer overlaps stored ones: a split shows as a constant close ratio (services/split_detection.py) and a restated close escalates the name to a full-depth 1d re-fetch in the same run. Was infra.bar_derivation.overlap_sessions (migration 406, value kept). Below threshold.seam.min_run plus one no split can be judged. Not an ML learning target.', '2026-10-03 15:32:51.485278+00');
INSERT INTO public.config_schema VALUES ('feature.momentum.window_slow', 'int', NULL, NULL, NULL, NULL, false, 1, 'Slow-scale momentum z-score lookback window (bars). [initial_estimate].', '2026-06-22 18:19:00.340925+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.ibkr_1d_reconcile_interval_days', 'int', '1', 1, 30, NULL, false, 1, '[user_preference] Completed NYSE sessions between update-lane IBKR 1d asks for one name: its 1d item is due when its latest answered SMART TRADES 1d request predates the close of the Nth latest completed session. 1 asks every name once after every session close (owner decision 2026-10-07: Tradier unfunded, IBKR is the 1d primary; the 7-day cadence of the design doc section 7 assumed Tradier was primary). A name whose latest canonical 1d bar trails the last completed session and that was not asked since its close is due whatever N is. Not an ML learning target.', '2026-10-08 04:04:59.347169+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.update_overlap_days_5m', 'int', '3', 0, 30, NULL, false, 1, '[initial_estimate] Calendar days the update lane re-asks behind a series'' latest stored 5m bar (IBKR restates recent intraday bars: 185-31 found 15 to 40 differing rows per name). Restated rows are written and recorded in ohlcv_revision by the ingress write contract; a median stored/fresh close ratio outside threshold.bar_integrity.fallback_basis_tolerance_bp escalates the name to a full-depth 5m re-fetch in the same run. Three days reach the prior session across a weekend inside the one request the 150-day chunk already makes; calibrate from ohlcv_revision ages once the update lane runs. Not an ML learning target.', '2026-10-08 04:04:59.347169+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.gap_fill_interval_days', 'int', '7', 1, 90, NULL, false, 1, '[initial_estimate] Sessions between gap-fill passes for one series: on one session in every N (the weekday index of the last completed session, offset per series by a stable hash so the work spreads evenly; a holiday slot skips that cycle) the series plans its full depth window (interior holes, short starts) instead of the update lane''s tail. Answered and empty windows are never re-asked, so a pass costs requests only where history is missing. Not an ML learning target.', '2026-10-08 04:04:59.347169+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.stall_tick_s', 'int', '60', 1, 600, NULL, false, 1, '[initial_estimate] Seconds between the fetcher stall watchdog''s progress checks (todo 538). Each tick compares the run''s forward-motion counter (phase completions and fetched items) against the last tick; stage subprocesses suspend the countdown. Not an ML learning target.', '2026-10-31 22:49:48.10504+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.stall_abort_s', 'int', '1800', 60, 7200, NULL, false, 1, '[initial_estimate] Zero-progress seconds after which the fetcher dumps every pending task at error level and exits 1 (todo 538). 1800 s cannot trip on legal pacing (the rate limiter window is 600 s), and one wedged run costs at most 30 minutes instead of hours. Not an ML learning target.', '2026-10-31 22:49:48.10504+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.teardown_timeout_s', 'int', '30', 5, 300, NULL, false, 1, '[initial_estimate] Budget for the fetcher''s whole leaf-disconnect sequence (todo 538); a teardown that exceeds it logs, fails the run loudly and lets the timer restart the lane, where the 2026-10-17 hangs parked forever. Not an ML learning target.', '2026-10-31 22:49:48.10504+00');
INSERT INTO public.config_schema VALUES ('feature.market_residual.z_window', 'int', '252', 2, 2000, NULL, false, 1, '[conventional] one trading year: Trailing window, in the name''s own daily bars, of the time-series z behind market_residual_z (Avellaneda-Lee 2010 ingredient). Cross-sectional standardization never happens in storage. Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('feature.idiosyncratic_volatility.window', 'int', '21', 2, 500, NULL, false, 1, '[conventional] monthly, Ang et al. 2006: Sample std (unannualized) window of the market residual behind idiosyncratic_volatility. Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('feature.market_residual.lag1_acf_window', 'int', '63', 3, 1000, NULL, false, 1, '[initial_estimate] one quarter: Window of the lag-1 autocorrelation of the market residual behind market_residual_lag1_acf; a no-spread window is NaN. Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('feature.residual_beta_stability.window', 'int', '60', 2, 1000, NULL, false, 1, '[initial_estimate]: Window of the sample std of the rolling equity beta behind residual_beta_stability (the dispersion estimator pinned by the review). Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('feature.max_daily_return.window', 'int', '21', 2, 500, NULL, false, 1, '[conventional] monthly, Bali et al. MAX: Window of the largest daily log return behind max_daily_return. Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('feature.max_drawdown.window', 'int', '252', 2, 2000, NULL, false, 1, '[conventional] one trading year: Window of the close-based maximum drawdown behind max_drawdown, stored in [0, 1]. Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('feature.downside_deviation.window', 'int', '252', 2, 2000, NULL, false, 1, '[conventional] one trading year: Window of the downside deviation (target 0) behind downside_deviation. Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('feature.size_proxy.window', 'int', '63', 2, 2000, NULL, false, 1, '[initial_estimate] one quarter: Window, in own-timeframe bars, of the mean ln(close * volume) behind size_proxy; runs per volume-basis segment. Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('feature.dividend_yield.window', 'int', '252', 2, 2000, NULL, false, 1, '[conventional] trailing twelve months: Window of trailing dividend amounts over the close behind dividend_yield; NaN while the window holds a date outside dividend_event_coverage. Changing it changes stored feature_vectors values (a rebuild of the column). Not an ML learning target.', '2026-11-03 23:02:53.395204+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.defer_after', 'json', '{}', NULL, NULL, NULL, false, 1, '[user_preference] {vendor: {timeframe: ISO instant}}. ohlcv_history_fetcher ends that series'' fetch plan at the instant instead of now (gaps and the update-lane overlap alike; an escalation re-asks its whole window), so the vendor budget goes first to history no other vendor holds; a series with nothing to ask before it is deferred (not asked, not recorded, n_deferred in the run summary). ''{}'' defers nothing; an unknown vendor, a timeframe outside 5m/15m/1h or a malformed instant fails the run. Seeded {"ibkr": {"5m": "2016-01-01T00:00:00+00:00"}} for the todo 534 pre-2016 IBKR 5m backfill; set ''{}'' when pre-2016 depth is complete. Parsed once per run by scripts/infrastructure/backfill/_history_fetch_item.parse_defer_after. Not an ML learning target.', '2026-11-03 23:04:41.431941+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.realized_vol_window', 'int', '20', NULL, NULL, NULL, false, 1, 'Rolling window (daily bars) for SPY realized vol (log-return std). [initial_estimate] Scaled to TF bars via _tf_window(daily, tf). ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.vol_window', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Rolling window (bars) for realized volatility computation in the HMM observation vector. Must match HMMRegimePlugin.vol_window for trainer/inference consistency. Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('infra.research.snapshot_feature_chunk_symbols', 'int', '100', 1, NULL, NULL, false, 1, '[initial_estimate] Symbols per feature-read chunk in research S0 (phase 184-08). Bounds the peak memory of a 5m read (a 5m column over ten years is about 196k rows per symbol); changes no value in any snapshot. Read by src/intelligence/research/snapshot.py. Not an ML learning target.', '2026-11-04 01:17:47.491485+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.grid_parity_sample_names_per_week', 'int', '10', 0, 500, NULL, false, 1, '[initial_estimate] Names a week whose vendor 15m and 1h are asked into the archive as the grid parity sample (design section 7): chosen by a stable hash of the ISO week among names holding both 5m and archive rows, the same names on every run of that week. 0 queues no 15m or 1h item. Replaces the unbounded vendor 15m/1h fetch that 189-07 stopped. Not an ML learning target.', '2026-10-08 04:04:59.347169+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.vix_z_window', 'int', '252', NULL, NULL, NULL, false, 1, 'Rolling window (daily bars) for VIX z-score mean/std normalization. [conventional] 252 trading days scaled via _tf_window(). ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.ma_window', 'int', '200', NULL, NULL, NULL, false, 1, 'Rolling window (daily bars) for 200MA breadth signal. [conventional] Scaled via _tf_window(). ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('alpha.validation.oos_start', 'string', '', NULL, NULL, NULL, false, 1, 'OOS holdout start timestamp (ISO8601 UTC). Set once during Phase 141 CORPUS-02. All IC measurement uses data BEFORE this timestamp. OOS used for final validation at Phase 142 exit gate only. [user_preference] ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.min_obs_per_regime', 'int', '3000', NULL, NULL, NULL, false, 1, 'Minimum independent observations per (symbol, tf, regime) cell required for IC score to count toward BH-FDR gate and ensemble weighting. [initial_estimate] IC Sharpe on <3K obs too noisy to survive BH-FDR. ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.1d', 'int', '7300', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 1d bars. [rca_analysis] Confirmed available via SPY probe 2026-06-19 (7300d exact, 2006-2026). ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.1h', 'int', '7300', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 1h bars. [rca_analysis] Confirmed available via SPY probe 2026-07-02 (175,191 bars back to 2006-07-07); prior 5475d (15yr) was a deliberate cap, not a proven ceiling. ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.15m', 'int', '7300', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 15m bars. [rca_analysis] Confirmed available via SPY probe 2026-07-02 (700,770 bars back to 2006-07-07); prior 3650d (10yr) was a deliberate cap, not a proven ceiling. ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.5m', 'int', '7300', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 5m bars. [rca_analysis] Confirmed available via SPY probe 2026-07-02 (2,102,364 bars back to 2006-07-07); prior 1631d (4.5yr) was a deliberate cap, not a proven ceiling. ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.1m', 'int', '90', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 1m bars. [initial_estimate] Deliberate storage/compute tradeoff, not a retention constraint — 1m patterns (time-of-day, day-of-week) repeat on weekly/monthly cycles so 90d captures full repetition. IBKR confirmed 10yr+ retention (SPY probe 2026-06-19). ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.default_scopes', 'json', '{"compute": ["1d", "1h", "15m", "5m"], "compute_1d": ["1d"], "backfill": ["1h", "15m"]}', NULL, NULL, NULL, false, 1, '[user_preference] The (eligibility dimension -> timeframes) union the IBKR history fetcher queues when run without --dimension/--timeframes/--symbols. Since 189-07: 1d and 5m for compute_1d; vendor 15m and 1h are asked only as the weekly parity sample (infra.backfill.grid_parity_sample_names_per_week) and the grid derives 15m and 1h from 5m. 1m is out (todo 455). A timeframe is added by an APR edit, not code. Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('infra.tradeable_series.fetch_block_rows', 'int', '10000', 1000, 1000000, NULL, false, 1, '[conventional] Rows per server-side cursor round trip in services/_batch_utils.py fetch_tradeable_series, the whole-series market_data_ohlcv_tradeable fetch the regime screening and golden-capture tools share (moved from the retired regime_writer, todo 590). Memory and round trips only; results do not depend on it. Not an ML learning target.', '2026-11-05 03:00:13.212862+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.n_components', 'int', '3', 2, 10, NULL, false, 1, '[583 refusal-rule study 2026-11-04, uniform across 1d/5m/15m/1h] Number of hidden states in the trend GaussianHMM: K=3 has the lowest share of refused walk-forward segments at every timeframe (5m 6.2% vs K4 7.9%, 15m 1.3% vs 3.5%, 1h 1.5% vs 5.5%; 1d from the rule on complete data). Replaced K=5 from the 2026-06-26 BIC study (migration 172); BIC prefers the grid edge K=6 everywhere and does not bound K here. Not an ML learning target (changes model topology, requires full retraining).', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('threshold.split_continuity.rel_tol', 'float', '0.3', 0.05, 0.49, NULL, false, 1, '[rca_analysis] Fraction of |log f| inside which a log close step counts as a split of factor f (todo 587). Used by ops_split_calendar_audit to confirm a calendar split (canonical steps by -log f, Yahoo split-adjusted close inside the band) and by the D7 split_continuity check (a step near -log f is still unadjusted, near +log f double-adjusted; either fails the name). Below 0.5 so the two bands and the continuous band never overlap. Not an ML learning target.', '2026-11-04 06:41:18.377092+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.cost_hurdle.5m', 'float', NULL, NULL, NULL, NULL, false, 1, 'Min CI lower bound (alpha_score units) for 5m emissions. Cost-aware directional gate: ci_lower must exceed this to pass. Initial 0.0 = no-op; raise after calibration from corpus data. [initial_estimate]', '2026-06-30 13:00:24.421853+00');
INSERT INTO public.config_schema VALUES ('feature.momentum.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Rolling z-score window for momentum, ~1 trading year. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.volume.zscore_window', 'int', '20', NULL, NULL, NULL, false, 1, '[conventional] Volume z-score rolling window. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.ofi.zscore_window', 'int', '20', NULL, NULL, NULL, false, 1, '[conventional] OFI z-score rolling window. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.cvd.slope_bars', 'int', '5', NULL, NULL, NULL, false, 1, '[conventional] CVD slope lookback bars. ML learning target after sufficient IC data.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.cmf.period', 'int', '20', NULL, NULL, NULL, false, 1, '[conventional] Chaikin Money Flow period. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.vol.short_bars', 'int', '5', NULL, NULL, NULL, false, 1, '[conventional] Short realized vol window bars. ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.vol.long_bars', 'int', '20', NULL, NULL, NULL, false, 1, '[conventional] Long realized vol window bars. ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.hma.period', 'int', '20', NULL, NULL, NULL, false, 1, '[conventional] Hull MA period for hma_slope_z computation. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.adx.period', 'int', '14', NULL, NULL, NULL, false, 1, '[conventional] ADX period. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.hurst.window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Hurst R/S rolling window, ~1 trading year. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.garch.window', 'int', '100', NULL, NULL, NULL, false, 1, '[initial_estimate] GARCH estimation window bars. ML learning target after sufficient IC data.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.vix.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] VIX z-score rolling window, ~1 trading year. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.yield_curve.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Yield curve z-score window, ~1 trading year. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.regime.cache_refresh_bars', 'int', '30', NULL, NULL, NULL, false, 1, '[initial_estimate] Regime feature recompute cadence in bars. Regime-level features (HMM, Hurst, Shannon, GARCH) are expensive; recompute every N bars and serve from cache. ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('alpha.vector.v1_quant.members', 'str', 'momentum_z_5,momentum_z_20,hma_slope_z,range_position,bar_close_pos,atr_z,vol_ratio,ctf_momentum', NULL, NULL, NULL, false, 1, '[initial_estimate] V1 Quant vector constituent primitives. Mutable via APR. IC discovery may prune members.', '2026-06-21 00:53:32.560163+00');
INSERT INTO public.config_schema VALUES ('feature.period.rsi.fast', 'int', '7', NULL, NULL, NULL, false, 1, '[conventional] RSI fast period (half Wilder canonical). ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.period.rsi.mid', 'int', '14', NULL, NULL, NULL, false, 1, '[conventional] RSI mid period (Wilder canonical). ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.period.rsi.slow', 'int', '28', NULL, NULL, NULL, false, 1, '[conventional] RSI slow period (double of canonical). ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
