INSERT INTO public.config_schema VALUES ('feature.period.cci.slow', 'int', '40', NULL, NULL, NULL, false, 1, '[initial_estimate] CCI slow period. ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.period.aroon.fast', 'int', '14', NULL, NULL, NULL, false, 1, '[initial_estimate] Aroon fast window. ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.period.aroon.slow', 'int', '25', NULL, NULL, NULL, false, 1, '[initial_estimate] Aroon slow window. ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.amihud.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Amihud illiquidity z-score window (~1 trading year). Not an ML learning target.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.ret_skew.window', 'int', '60', NULL, NULL, NULL, false, 1, '[initial_estimate] Rolling window for return skewness computation. ML learning target.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.ret_skew.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Z-score window for return skewness (~1 trading year). Not an ML learning target.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.ret_acf.window', 'int', '30', NULL, NULL, NULL, false, 1, '[initial_estimate] Rolling window for ACF lag-1 computation. ML learning target.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.ret_acf.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Z-score window for ACF lag-1 (~1 trading year). Not an ML learning target.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.high_52w.window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] 52-week high window (252 trading days). Not an ML learning target.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.cache.min_bars_warmup', 'int', '16', NULL, NULL, NULL, false, 1, 'Minimum bars required before any regime computation in FeatureCache. [initial_estimate]', '2026-06-22 00:12:53.981132+00');
INSERT INTO public.config_schema VALUES ('feature.cross_asset.rv_window', 'int', '20', NULL, NULL, NULL, false, 1, 'Realized vol window for SPY cross-asset z-score in FeatureCache. [initial_estimate]', '2026-06-22 00:12:53.981132+00');
INSERT INTO public.config_schema VALUES ('feature.session.ny_start_utc_hour', 'int', '13', NULL, NULL, NULL, false, 1, 'NY RTH open hour in UTC (09:30 ET = 13:30 UTC winter). [conventional]', '2026-06-22 00:12:53.981132+00');
INSERT INTO public.config_schema VALUES ('feature.session.ny_start_utc_minute', 'int', '30', NULL, NULL, NULL, false, 1, 'NY RTH open minute in UTC. [conventional]', '2026-06-22 00:12:53.981132+00');
INSERT INTO public.config_schema VALUES ('feature.session.ny_end_utc_hour', 'int', '20', NULL, NULL, NULL, false, 1, 'NY RTH close hour in UTC (16:00 ET = 20:00 UTC winter). [conventional]', '2026-06-22 00:12:53.981132+00');
INSERT INTO public.config_schema VALUES ('feature.session.overlap_start_utc_hour', 'int', '12', NULL, NULL, NULL, false, 1, 'London-NY overlap start UTC hour. [conventional]', '2026-06-22 00:12:53.981132+00');
INSERT INTO public.config_schema VALUES ('feature.session.overlap_end_utc_hour', 'int', '15', NULL, NULL, NULL, false, 1, 'London-NY overlap end UTC hour. [conventional]', '2026-06-22 00:12:53.981132+00');
