INSERT INTO public.config_schema VALUES ('feature.session.opening_range_start_minute', 'int', '810', NULL, NULL, NULL, false, 1, 'Opening range start as minutes-since-midnight UTC (13:30 = 810). [conventional]', '2026-06-22 00:12:53.981132+00');
INSERT INTO public.config_schema VALUES ('feature.session.opening_range_end_minute', 'int', '900', NULL, NULL, NULL, false, 1, 'Opening range end as minutes-since-midnight UTC (15:00 = 900). [conventional]', '2026-06-22 00:12:53.981132+00');
INSERT INTO public.config_schema VALUES ('feature.momentum.window_fast', 'int', '5', NULL, NULL, NULL, false, 1, '[conventional] Short momentum lookback bars. ML learning target after sufficient IC data.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.momentum.window_mid', 'int', '20', NULL, NULL, NULL, false, 1, '[conventional] Long momentum lookback bars. ML learning target after sufficient IC data.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.min_observations', 'int', '500', 100, 10000, NULL, false, 1, '[rca_analysis] Minimum independent observations required for IC estimation. At N=100 the CI on IC=0.04 is approximately ±0.10, wider than the signal itself. At N=500 it narrows to ±0.04. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.fetch_concurrency', 'int', '1', 1, 8, NULL, false, 1, '[initial_estimate] Queue items the fetcher loop runs at once (one request in flight each). 1 is serial. 5m answers in a median 28 s, so 3-4 reaches the 348/hour limiter ceiling; the shared sliding-window limiter still paces every request. ML learning target: recalibrate against measured pacing pushback (todo 505).', '2026-10-13 02:48:31.906615+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.cost_hurdle.15m', 'float', NULL, NULL, NULL, NULL, false, 1, 'Min CI lower bound (alpha_score units) for 15m emissions. [initial_estimate]', '2026-06-30 13:00:24.421853+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.cost_hurdle.1h', 'float', NULL, NULL, NULL, NULL, false, 1, 'Min CI lower bound (alpha_score units) for 1h emissions. Costs negligible at hourly horizon; set to 0.0. [user_preference]', '2026-06-30 13:00:24.421853+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.cost_hurdle.1d', 'float', NULL, NULL, NULL, NULL, false, 1, 'Min CI lower bound (alpha_score units) for 1d emissions. Costs negligible at daily horizon; set to 0.0. [user_preference]', '2026-06-30 13:00:24.421853+00');
INSERT INTO public.config_schema VALUES ('infra.alpaca.rate_limit_max_requests', 'int', '190', 1, 200, NULL, false, 1, '[measured 2026-10-10] Alpaca bars requests per minute, sustained (the capture leaf''s native pacing). 190/min clean across the 1,529-name scratch pull (~119k requests, zero 429s); documented Basic cap 200. ML learning target: recalibrate when the tier changes.', '2026-10-10 21:19:48.871325+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.fdr_alpha', 'float', '0.05', 0.001, 0.2, NULL, false, 1, '[conventional] Benjamini-Hochberg FDR correction q-value for multiple-testing correction across the full feature universe. 0.05 is the conventional choice for financial IC studies. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.walk_forward_folds', 'int', '3', 2, 10, NULL, false, 1, '[conventional] Number of chronological walk-forward validation folds. 3 folds is the conventional minimum for out-of-sample stability assessment given data depth constraints. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('infra.alpaca.nightly_window_days', 'int', '5', 1, 30, NULL, false, 1, '[conventional] The nightly capture leaf''s lookback window in calendar days: 5 days of 5m tail covers weekends and a holiday Monday with margin at 1-minute grain; the gap planner re-asks anything the window misses.', '2026-10-10 21:19:48.871325+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.sharpe_min_windows', 'int', '10', 3, 50, NULL, false, 1, '[conventional] Minimum number of rolling IC windows required to compute IC Sharpe. Below this threshold ic_sharpe is NULL. 10 windows is the conventional minimum for a time-series t-test to have power. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.subsample_min_stride', 'int', '5', 1, 60, NULL, false, 1, '[conventional] Minimum sampling stride for non-overlapping IC observations. Actual stride = max(subsample_min_stride, lookahead_bars). This ensures non-overlapping observations for all lookaheads: a fixed stride of 5 on a 20-bar lookahead would produce overlapping returns and corrupt the independence assumption required for block bootstrap and IC Sharpe computation. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.min_reliable_n', 'int', '100', 20, 1000, NULL, false, 1, '[conventional] n_independent threshold for the reliable flag on feature_ic_scores rows. Below this threshold the IC estimate is recorded but marked unreliable; it is excluded from ensemble weight computation. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.alpaca_basis_tolerance_bp', 'float', '1.0', 0, 1000, NULL, false, 1, '[pilot-measured 2026-10-09] Basis tolerance in bp of mid for the D7 alpaca_basis flag on dual-tape 5m names, where mid = (stored IBKR close + stored Alpaca close) / 2 on the sampled slot. The effective tolerance is max(this value, half-tick/mid from get_tick_size). Measured by the Alpaca integration pilot: sub-tick vendor tape differences dominate below 2 bp on 1-cent-tick instruments (docs/plans/2026-10-09-alpaca-5m-admission-build.md, T1 results). Not an ML learning target.', '2026-10-09 21:32:46.740644+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.session_close_settle_s', 'int', '1800', 0, 86400, NULL, false, 1, '[initial_estimate] Seconds after the NYSE session close before a bar ending at or after the close counts as a complete vendor answer: closing auction prints revise the last bar after the close (ADM 2026-10-12 19:55 UTC, 380,459 then 380,759). Applies to every vendor through src/intelligence/bars/complete_bars.py. Not an ML learning target.', '2026-10-14 20:06:43.46671+00');
INSERT INTO public.config_schema VALUES ('infra.selection_gate.request_load_match_s', 'int', '5', 1, 600, NULL, false, 1, '[rca_analysis] Largest gap, in seconds, between a request''s answered_at and the ohlcv_load row that persisted it, for loads that carry no request id (the retired fetch path). Measured 2026-10-14: applied 0.21 s max, refused 2.3 s max. Used by the selection gate and the raw repair for exact-key re-serve evidence. Not an ML learning target.', '2026-10-14 20:06:43.46671+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_flag_share', 'float', '0.02', 0, 1, NULL, false, 1, '[conventional] A vendor load whose changed rows exceed this share of its stored rows at the offered keys is flagged for review (D-191-N). Reporting only: the write lands last-wins regardless. Same level the retired refusal used. Not an ML learning target.', '2026-10-15 01:37:21.579532+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.random_state', 'int', NULL, 0, 99999, NULL, false, 1, '[conventional] numpy random seed for GaussianHMM fitting in regime_writer. CHANGING THIS INVALIDATES all regime labels in feature_vectors and requires full regime_writer + ic_engine re-run.', '2026-06-23 01:28:29.943433+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.split_ratio_max_numerator', 'int', '50', 2, 1000, NULL, false, 1, '[initial_estimate] Largest numerator of a recognised split ratio p/q (the larger term of the ratio read as a number above 1, so 20 for 1-for-20). A constant overlap rescale is recorded as a split or reverse_split only when its factor or the inverse is p/q within infra.backfill.split_ratio_rel_tol with p and q under their caps; otherwise the name is held as an unclassified rescale (services/bar_hold.py, plan 185-51). Equal to the snap bound of infer_split. Not an ML learning target.', '2026-10-08 21:45:38.173009+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.split_ratio_max_denominator', 'int', '4', 1, 50, NULL, false, 1, '[initial_estimate] Largest denominator of a recognised split ratio p/q (3-for-2 has 2, 5-for-4 has 4). Real splits are small integer ratios; the CTVA spin-off rescale of 2026-10-08 (39/7) was recorded as a split under the snap bound alone (todo 515). Not an ML learning target.', '2026-10-08 21:45:38.173009+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.split_ratio_rel_tol', 'float', '0.002', 1e-05, 0.05, NULL, false, 1, '[initial_estimate] Relative distance between a measured overlap rescale factor and p/q within which it is a recognised split ratio. Equal to threshold.seam.rel_tol, the constancy a seam already needs; measured: ETHA 1-for-3 exact, CTVA 5.5711 is 1.3 percent from 11/2. A rescale within this distance of a small ratio still passes. Not an ML learning target.', '2026-10-08 21:45:38.173009+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.future_bar_tolerance_s', 'int', '3600', 0, NULL, NULL, false, 1, '[initial_estimate] Seconds past now a bar timestamp may lie before the raw writer refuses it. A forming IBKR slot is at most one bar ahead, so 3600 covers 1h bars. Not an ML learning target.', '2026-10-13 03:12:46.185583+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_shift_min_share', 'float', '0.5', 0, 1, NULL, false, 1, '[initial_estimate] time_shift signature: share of changed bars whose new value equals the stored value one bar earlier or later. Reporting only (D-191-N). Not an ML learning target.', '2026-10-15 01:37:21.579532+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.threshold.5m', 'float', '1.5', 0.1, 5, NULL, false, 1, '[initial_estimate] Alpha emission threshold for 5m timeframe in composite z-score units. The alpha score is sum(w_i * z_i) where z_i are already z-scored features — this threshold is in the natural units of that composite (not in return units). Higher bar for short TF: more noise, higher transaction cost per unit time. Recalibrate post corpus run by computing E[return | alpha_score > threshold] from ensemble_alpha joined to forward_returns, then set threshold so expected return exceeds transaction cost (typically 5-10 bps for liquid ETFs at 5m). NOT an ML learning target.', '2026-06-24 05:28:46.478845+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.threshold.15m', 'float', '1.2', 0.1, 5, NULL, false, 1, '[initial_estimate] Alpha emission threshold for 15m timeframe in composite z-score units. Lower bar than 5m: longer holding periods reduce transaction cost per unit time, permitting lower alpha confidence for economic viability. Recalibrate post corpus run (see alpha.quant.threshold.5m for methodology). NOT an ML learning target.', '2026-06-24 05:28:46.478845+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.threshold.1h', 'float', '1.0', 0.1, 5, NULL, false, 1, '[initial_estimate] Alpha emission threshold for 1h timeframe in composite z-score units. Lower bar than 15m: 1h holding periods further reduce transaction cost per unit time. Approximately one composite standard deviation from zero as a conservative initial estimate. Recalibrate post corpus run (see alpha.quant.threshold.5m for methodology). NOT an ML learning target.', '2026-06-24 05:28:46.478845+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.threshold.1d', 'float', '0.8', 0.1, 5, NULL, false, 1, '[initial_estimate] Alpha emission threshold for 1d timeframe in composite z-score units. Lowest bar: daily holding periods minimize transaction cost per unit time and allow more persistent alpha with lower instantaneous signal strength. Recalibrate post corpus run (see alpha.quant.threshold.5m for methodology). NOT an ML learning target.', '2026-06-24 05:28:46.478845+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_flag_min_stored', 'int', '78', 0, 1000000, NULL, false, 1, '[rca_analysis] Stored rows a load must overlap before its changed share (the informational share signature) is judged: one regular 5m session, so the nightly overlap is judged (fourth review of 191-07; was 500). Basis signatures never wait on it. Not an ML learning target.', '2026-10-15 01:37:21.579532+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.obs_momentum_window', 'int', '20', 5, 200, NULL, false, 1, '[initial_estimate] N-bar window for the momentum observation feature in the 5D HMM observation vector. Computed as sum(log_returns[-N:]) / (realized_vol + eps), capturing directional drift normalized by vol. 20 bars = one trading day at 5m. Not an ML learning target.', '2026-06-25 13:01:50.66779+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.obs_vol_of_vol_window', 'int', '20', 5, 200, NULL, false, 1, '[initial_estimate] M-bar window for the vol-of-vol observation feature: rolling std of realized_vol. Stable regimes have stable realized_vol; transitions have erratic realized_vol. 20 bars = one trading day at 5m. Not an ML learning target.', '2026-06-25 13:01:50.66779+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_signature_min_bars', 'int', '5', 1, 100000, NULL, false, 1, '[rca_analysis] Changed bars a load needs before a basis-change signature (price_ratio, volume_ratio, time_shift) is tested; low enough for a short 1d overlap (fourth review of 191-07; was 20). Not an ML learning target.', '2026-10-15 01:37:21.579532+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_ratio_tolerance', 'float', '0.0005', 0, 1, NULL, false, 1, '[initial_estimate] price_ratio signature: relative distance of each changed price from the median new/old multiple, on top of the cent rounding of both answers. Not an ML learning target.', '2026-10-15 01:37:21.579532+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.session_probe_timeout_s', 'float', '10.0', 1, 120, NULL, false, 1, '[initial_estimate] Seconds IBKRProvider.session_alive waits for reqCurrentTime before calling the IBKR session dead (todo 577 qualify-on-dead-socket probe; todo 585). Too short reads a busy live session as lost and ends the fetcher run gateway_lost; too long delays the fast fail on a real loss. Loaded by apply_hist_rate_limit_config (HIST_RATE_LIMIT_KEYS). Not an ML learning target.', '2026-11-04 01:32:00.336836+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.n_iter', 'int', '200', 10, 500, NULL, false, 1, '[conventional] Maximum Baum-Welch EM iterations for GaussianHMM training. 200 provides convergence headroom for 470k-row 5m series where the near-IID return distribution makes EM slow to converge. Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('infra.feature_factory.workers', 'int', '12', 1, 32, NULL, false, 1, '[initial_estimate] Number of ProcessPoolExecutor workers for backfill_feature_factory.py symbol-level parallelism. Each worker opens its own psycopg2 connection. Default 12 = min(24_cores // 2, 16). Not an ML learning target.', '2026-06-25 15:58:18.142449+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.truncated_bar_volume_ratio', 'float', '0.2', 0, 1, NULL, false, 1, '[rca_analysis] A vendor bar is a truncated-bar candidate when its volume ratio to the other vendor''s bar at the same slot, over the session''s median ratio, is below this share (2026-10-09 14:10 truncated IBKR bars were under a fifth of Alpaca''s volume). Read-only scan (ops_truncated_bar_scan.py). Not an ML learning target.', '2026-10-15 01:45:27.774869+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_ratio_min_share', 'float', '0.8', 0, 1, NULL, false, 1, '[initial_estimate] price_ratio and volume_ratio signatures: share of the changed bars that must agree with the median new/old multiple, so a few unrelated corrected bars in the same re-serve do not hide a split. Reporting and review only (D-191-N). Not an ML learning target.', '2026-10-15 10:59:06.25493+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_ratio_min_move', 'float', '0.002', 0, 1, NULL, false, 1, '[initial_estimate] price_ratio signature: the median price multiple must differ from 1 by more than this (and by more than two ticks on the typical price). Not an ML learning target.', '2026-10-15 10:59:06.25493+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_price_tick', 'float', '0.01', 0, 1, NULL, false, 1, '[conventional] The price grid vendor answers are rounded to (US equities quote in cents above 1 dollar): the price_ratio test allows the rounding of both answers. Not an ML learning target.', '2026-10-15 10:59:06.25493+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_volume_tolerance', 'float', '0.01', 0, 1, NULL, false, 1, '[initial_estimate] volume_ratio signature: relative distance of a changed bar''s volume from the median multiple, plus one unit of the coarser volume grid. Not an ML learning target.', '2026-10-15 10:59:06.25493+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_integrity.restatement_volume_min_move', 'float', '0.2', 0, 100, NULL, false, 1, '[initial_estimate] volume_ratio signature: the median volume multiple must differ from 1 by more than this; routine late-print revisions move volume by a few percent and vary by bar. Not an ML learning target.', '2026-10-15 10:59:06.25493+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.vix_low_pct', 'float', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] VIX percentile threshold below which market is low-vol regime. Computed from SPY realized-vol z-score rolling percentile rank. Candidate ML learning target.', '2026-06-26 14:14:27.938805+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.vix_high_pct', 'float', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] VIX percentile threshold above which market is high-vol regime. Computed from SPY realized-vol z-score rolling percentile rank. Candidate ML learning target.', '2026-06-26 14:14:27.938805+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.breadth_bear', 'float', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] Fraction of equity ETFs above 200MA below which breadth is bearish. Computed from cross-sectional 200MA signal across all 58 equity ETFs. Candidate ML learning target.', '2026-06-26 14:14:27.938805+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.breadth_bull', 'float', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] Fraction of equity ETFs above 200MA above which breadth is bullish. Computed from cross-sectional 200MA signal across all 58 equity ETFs. Candidate ML learning target.', '2026-06-26 14:14:27.938805+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.equity_model_enabled', 'bool', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] If true, IC engine reads regime from market_regimes join AND computes cross-sectional pooled IC across all equity ETFs. If false, falls back to feature_vectors.regime and per-symbol IC only. Allows revert if cross-sectional model fails Phase 141 validation.', '2026-06-26 14:14:27.938805+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.hac_max_lag', 'int', '3', 0, 20, NULL, false, 1, '[initial_estimate] Bartlett-kernel max lag K for Newey-West HAC correction of the rolling-window IC Sharpe. K=0 disables HAC correction (ic_sharpe_hac == ic_sharpe). K=3 is standard for a 30-100 window IC series. Increase if IC autocorrelation at lag 3+ is material. Not an ML learning target -- methodological parameter. Inflates Sharpe denominator by sqrt(1 + 2*sum_k w_k*rho_k) where w_k = Bartlett weight.', '2026-06-26 20:14:08.321226+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.min_obs_daily_features', 'int', '1000', 1, NULL, NULL, false, 1, '[initial_estimate] Minimum independent observations for IC Sharpe gate applied exclusively to features sourced from context_features (daily cadence). Daily features have ~252 obs/year; this gate is ~4 years of history. Do NOT apply the intraday 20K gate to daily-cadence features — calibrated for different observation frequency. Not an ML learning target (depends on available history length, not model quality).', '2026-06-26 17:18:06.775803+00');
INSERT INTO public.config_schema VALUES ('infra.alpaca.artifact_max_answer_lag_hours', 'float', '120', 1, 2160, NULL, false, 1, '[initial_estimate] Largest gap in hours between an Alpaca artifact''s newest bar and its recorded answer time that ops_bar_load accepts (a weekend plus a holiday plus a long pull). A larger gap means a rewritten or copied artifact; it is refused. Not an ML learning target.', '2026-10-15 17:00:58.993213+00');
INSERT INTO public.config_schema VALUES ('feature.breakout.dist_window_slow', 'int', '50', 10, 300, NULL, false, 1, '[conventional] Slow rolling window (bars) for dist_from_high/low_slow. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('alpha.validation.oos_significant_drop_fraction', 'float', '0.5', NULL, NULL, NULL, false, 1, 'Fraction of in-sample qualifying-cell count below which the OOS holdout diagnostic scorer (ops_oos_holdout_eval.py, non-gating) reports a "significant drop — investigate" verdict for a TF. [initial_estimate]', '2026-07-02 13:31:17.848809+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.covariance_type', 'str', 'full', NULL, NULL, '{full,diag,tied}', false, 1, 'GaussianHMM covariance structure. "full" captures cross-correlations between obs dims; "diag" assumes independence (faster, less expressive); "tied" shares one matrix. Falls back to "diag" if n_obs < full_cov_min_obs. [initial_estimate]', '2026-06-28 04:19:51.030069+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.min_hold_bars', 'int', '3', NULL, NULL, NULL, false, 1, 'Minimum consecutive bars a new decoded state must persist before the transition is confirmed. Prevents single-bar flips when alpha is diffuse. Introduces at most min_hold_bars of lag on genuine transitions. [initial_estimate]', '2026-06-28 04:19:51.030069+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.full_cov_min_obs', 'int', '500', NULL, NULL, NULL, false, 1, 'Minimum observation count required to use covariance_type=full. Below this threshold regime_writer falls back to "diag" to avoid overfitting. [initial_estimate]', '2026-06-28 04:19:51.030069+00');
INSERT INTO public.config_schema VALUES ('feature.breakout.dist_window_fast', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Fast rolling window (bars) for dist_from_high/low_fast and new_high/low_flag. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.shrinkage_k', 'float', '100', NULL, NULL, NULL, false, 1, '[initial_estimate, ML learning target] E1 shrinkage effective-sample-size calibration constant: w = n_eff/(n_eff+k), the weight placed on a cell''s own raw ic_sharpe_hac vs. its leave-one-out peer-group prior. Seeded so a cell at exactly min_reliable_n=100 gets ~50% shrinkage toward its peer-group prior (n_eff=k -> w=0.5). Validated and recalibrated by the D-05 out-of-fold acceptance test. See todo 029 for the shrinkage design.', '2026-07-03 09:38:25.333748+00');
INSERT INTO public.config_schema VALUES ('alpha.ensemble.mv_condition_max', 'float', '1000', NULL, NULL, NULL, false, 1, '[initial_estimate] E2 gate: maximum allowed np.linalg.cond(cov_matrix) (2-norm condition number) before the Sigma^-1 . IC mean-variance solve is considered ill-conditioned and E2 falls back to the existing cluster_deflate_weights path (RESEARCH.md Assumption A3, Pitfall 3). Slated for recalibration once real condition-number distributions are observed from the first mean_variance run. NOT an ML learning target.', '2026-07-03 09:38:25.333748+00');
INSERT INTO public.config_schema VALUES ('infra.instruments_listener.heartbeat_s', 'int', '10', 1, NULL, NULL, false, 1, '[initial_estimate] Seconds between checks that the LISTEN instruments connection is still open; bounds how long a dropped connection goes unnoticed before a reconnect. Value carried over from the v2.x CacheManager. Not an ML learning target.', '2026-10-26 09:24:36.010193+00');
INSERT INTO public.config_schema VALUES ('infra.instruments_listener.reconnect_backoff_s', 'int', '5', 1, NULL, NULL, false, 1, '[initial_estimate] Seconds to wait before reconnecting the LISTEN instruments connection after a failure. Value carried over from the v2.x CacheManager. Not an ML learning target.', '2026-10-26 09:24:36.010193+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.chunk_days.1m', 'int', '6', NULL, NULL, NULL, false, 1, 'Per-request duration ceiling (days) for reqHistoricalDataAsync at 1m bar size. [rca_analysis] IBKR per-request limit ~7 days at this granularity; retention is 10+ years but each single request must stay under this window. Not an ML target.', '2026-07-05 14:36:40.558152+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.chunk_days.5m', 'int', '89', NULL, NULL, NULL, false, 1, '[rca_analysis] Verified 90D succeeds, 180D times out; 89D leaves margin. Was 29d -- the original cap predated the sliding-window rate limiter and likely conflated pacing (Error 162) with a true duration ceiling. Re-verified 2026-07-02 via direct probes on DBC/PPLT/SDOG. Not an ML target.', '2026-07-05 14:36:40.558152+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.chunk_days.15m', 'int', '59', NULL, NULL, NULL, false, 1, '[initial_estimate] Per-request limit ~60 days. Unlike 5m/1h, this value has not had a 2026-07-02-style re-verification probe -- flagged as possibly under-tuned (15m bars are less dense than 5m, so a larger ceiling may be tolerable). Not an ML target; recalibrate empirically before trusting as a true ceiling.', '2026-07-05 14:36:40.558152+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.chunk_days.1h', 'int', '364', NULL, NULL, NULL, false, 1, '[rca_analysis] Verified 364D succeeds cleanly, matching 1d. Was reduced to 29d after "some ETFs" failed on 2026-06-22 (commit 8472a074); re-verified 2026-07-02 via direct probes on DBC/SPHB/IPO/PPLT/SDOG, all succeeded -- likely the same pacing/duration conflation as 5m. Not an ML target.', '2026-07-05 14:36:40.558152+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.chunk_days.4h', 'int', '29', NULL, NULL, NULL, false, 1, '[initial_estimate] Per-request duration ceiling (days) for 4h bar size. Not re-verified alongside 5m/1h on 2026-07-02. Not an ML target.', '2026-07-05 14:36:40.558152+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.chunk_days.1d', 'int', '364', NULL, NULL, NULL, false, 1, '[rca_analysis] 1-year chunks; daily bars support full-year requests cleanly. ~20 chunks needed for 20yr depth. Not an ML target.', '2026-07-05 14:36:40.558152+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.contract_details_timeout_sec', 'float', '30', NULL, NULL, NULL, false, 1, '[rca_analysis] Outer asyncio.wait_for() timeout wrapping each reqContractDetailsAsync call (qualify_instrument, resolve_instrument). Unlike reqHistoricalDataAsync, this ib_insync call has NO internal timeout of its own -- fully unbounded without this wrapper, same failure class as the 2026-07-05 backfill hang. Not an ML target.', '2026-07-05 21:03:40.667873+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.min_state_occupation', 'float', '0.05', 0.005, 0.3, NULL, false, 1, '[initial_estimate] Minimum alpha-pass occupation fraction any HMM state must hold across the smoothed label sequence; below this the model is degenerate and its labels are skipped (P2b). Not an ML learning target.', '2026-07-06 12:30:33.945753+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.churn_window', 'int', '10', 3, 100, NULL, false, 1, '[initial_estimate] Rolling window (bars) over which hmm_churn is computed as the fraction of prior-window bars where the regime label changed (P2c). Not an ML learning target.', '2026-07-06 12:30:33.945753+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.historical_request_timeout_sec', 'float', '90', NULL, NULL, NULL, false, 1, '[rca_analysis] Outer asyncio.wait_for() timeout wrapping each reqHistoricalDataAsync call, on top of ib_async''s own internal timeout. Added after a 2026-07-05 backfill hang where the internal timeout never fired despite 25+ minutes elapsed (py-spy/strace: the process was idle, not blocked). Not a guaranteed fix for asyncio timer reliability: the fetcher''s per-item stall bound (infra.ibkr.history_request_timeout) and the indicagent-ibkr-history-fetcher unit''s WatchdogSec are the safety nets. Not an ML target.', '2026-07-05 20:44:52.045108+00');
INSERT INTO public.config_schema VALUES ('infra.old_store_backup.disk_margin', 'int', '2', 1, NULL, NULL, false, 1, '[initial_estimate] Free-disk multiplier for the old-store COPY backup dump (phase 191 plan 16): a dump needs free space >= estimated output (pg_total_relation_size of ohlcv_observation plus ohlcv_intraday_raw_archive) times this margin. 2 covers the gzip output against the on-disk estimate. Not an ML learning target.', '2026-10-17 04:09:15.804337+00');
INSERT INTO public.config_schema VALUES ('infra.selection_gate.statement_timeout_s', 'int', '7200', 1, NULL, NULL, false, 1, '[initial_estimate] Statement timeout (seconds) for the selection gate connection (phase 191 plan 16): --compare and --emit-spans scan full canonical series per name, so the gate needs a long-running-statement budget of its own. Seed value carries over infra.raw_backfill.statement_timeout_s (migration 381) as plan 191-16 deleted that key with ops_raw_backfill.py. Not an ML learning target.', '2026-10-17 05:50:10.358143+00');
