INSERT INTO public.config_schema VALUES ('feature.ret_kurtosis.fast', 'int', '30', 10, 100, NULL, false, 1, '[conventional] Fast rolling window (bars) for ret_kurtosis_z_fast excess-kurtosis estimate. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
