INSERT INTO public.config_schema VALUES ('feature.streak.window', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Normalization window (bars) for streak_z (signed directional streak length z-score). Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
